<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileBirthdateAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileBirthdateAccessor trait.
 *
 * Covers null default, string/VO assignment via withBirthdate,
 * getBirthdate/birthdate accessors, and isBirthdateChanged with/without original.
 */
class UserProfileBirthdateAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withBirthdate creates a new instance with the Birthdate set
     * from a string value, and getBirthdate returns the primitive string.
     */
    public function testWithBirthdateFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileBirthdateAccessorUnitTest();

        // Act
        $result = $holder->withBirthdate('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getBirthdate());
    }
    /**
     * Asserts that withbirthdate has access to the value object
     * from a string value, and getBirthdate returns the primitive string.
     */
    public function testWithBirthdateFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileBirthdateAccessorUnitTest();

        // Act
        $result = $holder->withBirthdate('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->birthdate()->value());
    }
    public function testChangedBirthdate(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileBirthdateAccessorUnitTest();
        $original = $holder->withBirthdate('one');
        $same = $holder->withBirthdate('one');
        $modified = $holder->withBirthdate('other');

        // Act
        $unchanged = $holder->isBirthdateChanged();
        $withSame = $original->isBirthdateChanged($same);
        $withDiferent = $original->isBirthdateChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileBirthdateAccessorUnitTest
{
    use UserProfileBirthdateAccessor;
}
